/**
 * The `@generated` header (SPEC-CONTRACTS §9):
 *   `// @generated by averri <version> from <id> hash:<sourceHash> — do not edit`
 * A6001 compares `hash:` with the Test node's `sourceHash`; a missing file is stale.
 */

import { isNodeId, type NodeId, type TestNode } from "@averri/ir";
import type { GeneratedHeader } from "./types.js";

export const GENERATED_HEADER_RE = /^\/\/ @generated by averri (\S+) from (\S+) hash:([0-9a-f]+) — do not edit\s*$/m;

/** Parse the header from the first line of a generated file; null when absent or malformed. */
export function parseGeneratedHeader(content: string): GeneratedHeader | null {
  const firstLine = content.split(/\r?\n/, 1)[0] ?? "";
  const m = GENERATED_HEADER_RE.exec(firstLine);
  if (!m) return null;
  const owner = m[2] as string;
  if (!isNodeId(owner)) return null;
  return { averriVersion: m[1] as string, owner: owner as NodeId, hash: m[3] as string };
}

/**
 * True when a generated Test node's file is missing (`content === null`), carries no header, names
 * another owner, or has a `hash:` that differs from `node.sourceHash`.
 */
export function isGeneratedTestStale(node: Pick<TestNode, "sourceHash" | "covers">, content: string | null): boolean {
  if (content === null) return true;
  const header = parseGeneratedHeader(content);
  if (!header) return true;
  if (node.sourceHash === undefined) return true;
  return header.hash !== node.sourceHash;
}
